import "fmt"

// ParseHex converts a hexadecimal string to its decimal (int64) equivalent
// using first principles, without relying on any conversion libraries.
func ParseHex(in string) (int64, error) {
	if len(in) == 0 {
		return 0, fmt.Errorf("syntax error: empty string")
	}

	var result int64
	for _, r := range in {
		var digit int64
		switch {
		case r >= '0' && r <= '9':
			digit = int64(r - '0')
		case r >= 'a' && r <= 'f':
			digit = int64(r-'a') + 10
		case r >= 'A' && r <= 'F':
			digit = int64(r-'A') + 10
		default:
			return 0, fmt.Errorf("syntax error: invalid character %q", r)
		}

		// Check for overflow before it happens.
		if result > (maxInt64-digit)/16 {
			return 0, fmt.Errorf("range error: value out of range for %q", in)
		}

		result = result*16 + digit
	}

	return result, nil
}

const maxInt64 = 1<<63 - 1

// HandleErrors takes a list of inputs for ParseHex and returns a matching
// list of error cases: "none", "syntax", or "range".
func HandleErrors(inputs []string) []string {
	results := make([]string, len(inputs))
	for i, in := range inputs {
		_, err := ParseHex(in)
		switch {
		case err == nil:
			results[i] = "none"
		default:
			msg := err.Error()
			if containsSubstring(msg, "syntax") {
				results[i] = "syntax"
			} else if containsSubstring(msg, "range") {
				results[i] = "range"
			} else {
				results[i] = "unknown"
			}
		}
	}
	return results
}

func containsSubstring(s, substr string) bool {
	for i := 0; i+len(substr) <= len(s); i++ {
		if s[i:i+len(substr)] == substr {
			return true
		}
	}
	return false
}
"}

